+fn line_before_call<'a>(program: &'a str, call: &str) -> Vec<&'a str> {
+    let lines: Vec<&str> = program.lines().collect();
+    lines
+        .windows(2)
+        .filter_map(|w| if w[1] == call { Some(w[0]) } else { None })
+        .collect()
+}
